    def isAlienSorted(self, words: List[str], order: str) -> bool:
        lookup = {c: i for i, c in enumerate(order)}
        for i in range(len(words)-1):
            word1 = words[i]
            word2 = words[i+1]
            for k in range(min(len(word1), len(word2))):
